  "anomalies": [
    {
      "category": "footprint_mismatch",
      "components": ["R1"],
      "pins": [],
      "nets": ["VIN+", "VIN-"],
      "observed": "The battery current-sense shunt is drawn as 'R1 10mOhm 1W 3512' — i.e. a 3512 land pattern.",
      "expected": "The specification states the shunt is 'R1 = 10 mΩ (1 W, 2512 package)'; the footprint should be 2512, not 3512.",
      "evidence": [
        {"source": "spec", "quote": "Battery current passes through shunt R1 = 10 mΩ (1 W, 2512 package), sensed differentially by INA219AIDCNR"},
        {"source": "schematic", "quote": "R1 10mOhm 1W 3512 (Power sheet, Battery Input and Current Sense Resistor block)"}
      ],
      "impact": "The board is laid out for a larger 3512 shunt than the specified 2512 part; the intended shunt will not fit the land pattern and a different physical part is assembled, so the build does not match the specified BOM/footprint.",
      "confidence": 0.5
    },
    {
      "category": "other",
      "components": ["U2", "U1"],
      "pins": ["U2.1", "U2.2", "U2.3", "U2.4", "U2.5", "U2.24", "U1.7", "U1.8"],
      "nets": ["I2C2_SCL_FCC", "I2C2_SDA_FCC"],
      "observed": "The PCA9685PW (U2) address pins A0–A5 are tied to GND, giving address 0x40, while the block's own note reads 'I2C address: 0x41'. The INA219 (U1) is also strapped to 0x40 (A0/A1 to GND) and is wired to the same I2C2_FCC bus (SDA/SCL labels I2C2_SDA_FCC / I2C2_SCL_FCC on both devices).",
      "expected": "The PWM driver must sit at a different address than the INA219 so both can share I2C2_FCC; the schematic's own note (0x41) indicates A0 was intended to be strapped high.",
      "evidence": [
        {"source": "schematic", "quote": "I2C address: 0x41 (FCC Peripherals sheet, PWM Driver block, U2 PCA9685PW)"},
        {"source": "schematic", "quote": "I2C address: 0x40 (Power sheet, Voltage/Current/Power Sense IC, U1 INA219AIDCNR)"},
        {"source": "spec", "quote": "PWM/servo driver | FCCPeripherals | NXP PCA9685PW (I2C 16-ch PWM), I2C addr 0x40"}
      ],
      "impact": "With both the INA219 and PCA9685 answering at 0x40 on the same I2C2_FCC bus, the FCC cannot reliably talk to both the servo driver and the current/voltage sensor (address collision).",
      "confidence": 0.4
    }
  ],
  "summary": "The drawing deviates from the specification in two places: the battery shunt R1 is drawn with a 3512 footprint instead of the specified 2512, and the PCA9685 PWM driver's I2C address is inconsistent (note says 0x41 while its address pins are grounded to 0x40, colliding with the INA219 also strapped to 0x40 on the same I2C2_FCC bus)."
}

